	@Test
	void failedFreezeCanBeClosedWithoutLeakingAdmittedResources() {
		List<String> events = new ArrayList<>();
		RecordingResource first = new RecordingResource("first", 1, events);
		RecordingResource second = new RecordingResource("second", 2, events);
		second.failureOnLock = new IllegalStateException("guard failure");

		try (StatementCountScope scope = scope(first, second)) {
			assertThrows(IllegalStateException.class, scope::freeze);
		}

		assertFalse(first.leaseHeld);
		assertFalse(second.leaseHeld);
		assertFalse(first.guardHeld);
		assertFalse(second.guardHeld);
		assertTrue(events.contains("first.unlock"));
		assertTrue(events.contains("first.releaseLease"));
		assertTrue(events.contains("second.releaseLease"));
	}

	@Test
	void closeActionsRunBeforeGuardsAndLeasesAreReleased() {
		List<String> events = new ArrayList<>();
		RecordingResource resource = new RecordingResource("resource", 1, events);
		StatementCountScope scope = scope(resource);
		scope.onClose(() -> {
			assertTrue(resource.guardHeld, "Native readers must close while the resource guard is held");
			assertTrue(resource.leaseHeld, "Native readers must close while the transaction lease is held");
			events.add("closeAction");
		});
		scope.onRelease(() -> {
			assertFalse(resource.guardHeld, "Lifetime reservations must release after guards");
			assertFalse(resource.leaseHeld, "Lifetime reservations must release after leases");
			events.add("releaseAction");
		});

		assertTrue(scope.freeze());
		scope.close();

		assertBefore(events, "closeAction", "resource.unlock");
		assertBefore(events, "closeAction", "resource.releaseLease");
		assertBefore(events, "resource.releaseLease", "releaseAction");
		assertFalse(resource.guardHeld);
		assertFalse(resource.leaseHeld);
	}

	@Test
	void provisionalReservationsReleaseWhenScopeClosesWithoutFreeze() {
		List<String> events = new ArrayList<>();
		RecordingResource resource = new RecordingResource("resource", 1, events);
		StatementCountScope scope = scope(resource);
		scope.onRelease(() -> {
			assertFalse(resource.guardHeld);
			assertFalse(resource.leaseHeld);
			events.add("provisionalRelease");
		});

		scope.close();

		assertTrue(events.contains("provisionalRelease"), "Unfrozen scopes must release preflight reservations");
		assertFalse(resource.guardHeld);
		assertFalse(resource.leaseHeld);
		assertThrows(IllegalStateException.class, scope::requireFrozen);
	}

	@Test
	void rejectedReleaseRegistrationClosesOwnerAndPreservesCleanupFailure() {
		StatementCountScope scope = new StatementCountScope(null, null, null, new Resource[0]);
		assertTrue(scope.freeze());
		AtomicInteger closeCalls = new AtomicInteger();
		IllegalStateException cleanupFailure = new IllegalStateException("owner cleanup failed");
		AutoCloseable owner = () -> {
			closeCalls.incrementAndGet();
			throw cleanupFailure;
		};

		IllegalStateException failure = assertThrows(IllegalStateException.class, () -> scope.onRelease(owner));

		assertEquals("Statement count resources must be registered before freeze", failure.getMessage());
		assertEquals(1, closeCalls.get(), "A rejected provisional owner must be closed immediately");
		assertTrue(List.of(failure.getSuppressed()).contains(cleanupFailure),
				"Owner cleanup failure must remain suppressed under the registration failure");
		scope.close();
	}

