	@Test
	void closeAttemptsEveryCleanupAndResourceReleaseAfterFailures() {
		List<String> events = new ArrayList<>();
		RecordingResource first = new RecordingResource("first", 1, events);
		RecordingResource second = new RecordingResource("second", 2, events);
		IllegalStateException firstCloseFailure = new IllegalStateException("first close action");
		IllegalStateException lastCloseFailure = new IllegalStateException("last close action");
		IllegalStateException firstUnlockFailure = new IllegalStateException("first unlock");
		IllegalStateException secondUnlockFailure = new IllegalStateException("second unlock");
		IllegalStateException firstLeaseFailure = new IllegalStateException("first lease release");
		IllegalStateException secondLeaseFailure = new IllegalStateException("second lease release");
		IllegalStateException releaseActionFailure = new IllegalStateException("reservation release");
		first.failureOnUnlock = firstUnlockFailure;
		second.failureOnUnlock = secondUnlockFailure;
		first.failureOnReleaseLease = firstLeaseFailure;
		second.failureOnReleaseLease = secondLeaseFailure;
		StatementCountScope scope = scope(first, second);
		scope.onClose(() -> {
			events.add("firstCloseAction");
			throw firstCloseFailure;
		});
		scope.onClose(() -> {
			events.add("lastCloseAction");
			throw lastCloseFailure;
		});
		scope.onRelease(() -> {
			events.add("reservationRelease");
			throw releaseActionFailure;
		});
		scope.onRelease(() -> events.add("finalReleaseAction"));
		assertTrue(scope.freeze());

		IllegalStateException failure = assertThrows(IllegalStateException.class, scope::close);

		assertSame(lastCloseFailure, failure, "The first cleanup failure must remain primary");
		assertTrue(List.of(failure.getSuppressed()).contains(firstCloseFailure));
		assertTrue(List.of(failure.getSuppressed()).contains(releaseActionFailure));
		assertTrue(events.containsAll(List.of("firstCloseAction", "lastCloseAction", "first.unlock", "second.unlock",
				"first.releaseLease", "second.releaseLease", "reservationRelease", "finalReleaseAction")));
		assertFalse(first.guardHeld);
		assertFalse(second.guardHeld);
		assertFalse(first.leaseHeld);
		assertFalse(second.leaseHeld);
		scope.close();
	}

